# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_tmux_bind_command() {
    _argc_util_comp_subcommand 1 tmux
}

_choice_tmux_border_lines() {
    printf '%s\n' single rounded double heavy simple padded none
}

_choice_tmux_buffer() {
    tmux list-buffers -F '#{buffer_name}' 2>/dev/null || true
}

_choice_tmux_client() {
    tmux list-clients -F '#{client_name}' 2>/dev/null || true
}

_choice_tmux_command() {
    local script="$ARGC_COMPLETIONS_ROOT/completions/tmux.sh"
    if [[ ! -f "$script" ]]; then
        script="${BASH_SOURCE[0]:-$0}"
    fi
    argc --argc-export "$script" | jq -b -r '.subcommands[] | .describe as $d | (.name, (.aliases[]?)) | . + "\t" + ($d // "")' || true
}

_choice_tmux_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_tmux_command
    else
        _argc_util_comp_subcommand 0 tmux
    fi
}

_choice_tmux_env_assignment() {
    [[ "$ARGC_CWORD" == *=* ]] && return 0
    _choice_tmux_environment | _argc_util_transform suffix== nospace
}

_choice_tmux_environment() {
    tmux show-environment -g 2>/dev/null | gawk -F= '{
        name = $1
        sub(/^-/, "", name)
        if (name != "") print name
    }' || true
}

_choice_tmux_hook() {
    tmux show-hooks -g 2>/dev/null | gawk '{
        name = $1
        sub(/\[.*/, "", name)
        if (name != "") print name
    }' || true
}

_choice_tmux_key() {
    tmux list-keys 2>/dev/null | gawk '$1 == "bind-key" && $2 == "-T" && $4 != "" { print $4 }' || true
}

_choice_tmux_key_table() {
    tmux list-keys -F '#{key_table}' 2>/dev/null || true
}

_choice_tmux_layout() {
    printf '%s\n' even-horizontal even-vertical main-horizontal main-horizontal-mirrored main-vertical main-vertical-mirrored tiled
}

_choice_tmux_option() {
    { tmux show-options -g; tmux show-options -g -w; tmux show-options -g -s; tmux show-options -g -p; } 2>/dev/null | gawk '{
        name = $1
        sub(/\[.*/, "", name)
        if (name != "") print name
    }' || true
}

_choice_tmux_pane() {
    tmux list-panes -a -F '#{session_name}:#{window_index}.#{pane_index}|#{pane_current_command}' 2>/dev/null | _argc_util_transform format='|' || true
}

_choice_tmux_prompt_type() {
    printf '%s\n' command search
}

_choice_tmux_session() {
    tmux list-sessions -F '#{session_name}|#{session_windows} windows' 2>/dev/null | _argc_util_transform format='|' || true
}

_choice_tmux_shell_command() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        if _argc_util_has_path_prefix; then
            _argc_util_comp_path
        else
            _argc_util_comp_command
        fi
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_tmux_window() {
    tmux list-windows -a -F '#{session_name}:#{window_index}|#{window_name}' 2>/dev/null | _argc_util_transform format='|' || true
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
